import { forwardRef, type ReactNode } from "react";

import { cn } from "@/lib/cn";
import { Button, type ButtonProps } from "./button.js";

/** Supported IconButton glyph sizes. */
export type IconButtonIconSize = "xs" | "sm" | "md" | "lg";

const iconSizeClasses = {
  xs: "size-3",
  sm: "size-[var(--stipe-icon-size-sm)]",
  md: "size-[var(--stipe-icon-size-md)]",
  lg: "size-[var(--stipe-icon-size-lg)]",
} satisfies Record<IconButtonIconSize, string>;

/** Props accepted by IconButton. */
export type IconButtonProps = {
  "aria-label": string;
  active?: boolean;
  icon: ReactNode;
  iconSize?: IconButtonIconSize;
  reveal?: boolean;
  size?: ButtonProps["size"] | "responsive";
  tone?: "default" | "destructive";
} & Omit<ButtonProps, "children" | "size">;

/** A compact button for an icon control with an accessible name supplied by the caller. */
export const IconButton = forwardRef<HTMLButtonElement, IconButtonProps>(
  function IconButton(
    {
      active = false,
      icon,
      iconSize = "xs",
      className,
      reveal = false,
      size = "xs",
      tone = "default",
      variant = "ghost",
      ...props
    },
    ref,
  ) {
    const responsive = size === "responsive";

    return (
      <Button
        {...props}
        // A result beat on an icon shows the check alone.
        resultLabel={props.result === undefined ? undefined : null}
        ref={ref}
        size={responsive ? "sm" : size}
        variant={variant}
        className={cn(
          "caps-icon-button btn-circle",
          responsive && "caps-icon-button-responsive md:btn-xs",
          active && "text-accent",
          reveal &&
            "scale-0 transition-transform group-hover:scale-100 focus-visible:scale-100",
          tone === "destructive" && "hover:text-error",
          className,
        )}
      >
        <span
          aria-hidden="true"
          className={cn(
            "inline-flex shrink-0 [&>svg]:size-full [&>svg]:[stroke-width:var(--stipe-icon-stroke)]",
            iconSizeClasses[iconSize],
          )}
        >
          {icon}
        </span>
      </Button>
    );
  },
);

import { Slot } from "@radix-ui/react-slot";
import {
  forwardRef,
  useEffect,
  useImperativeHandle,
  useLayoutEffect,
  useRef,
  useState,
  type ButtonHTMLAttributes,
  type ElementRef,
  type ReactNode,
  type RefObject,
} from "react";

import { cn, cva } from "@/lib/cn";
import {
  canAnimate,
  motionEasing,
  readMotion,
  useReducedMotion,
  type Motion,
} from "@/lib/motion";
import { Loader } from "./loader.js";

/** Supported Button visual variants. */
export type ButtonVariant =
  | "primary"
  | "secondary"
  | "accent"
  | "destructive"
  | "outline"
  | "ghost"
  /** Quiet text that turns to the error colour on hover or focus, e.g. Stop. */
  | "ghost-destructive"
  | "link";
/** Supported ButtonSize values. */
export type ButtonSize = "xs" | "sm" | "default" | "lg" | "icon" | "menubar";

/** Outline and link controls keep a neutral disabled plate behind a hairline. */
const disabledPlate =
  "disabled:bg-base-200 disabled:text-base-content disabled:outline-1 disabled:outline-solid disabled:outline-base-content/25 aria-disabled:bg-base-200 aria-disabled:text-base-content aria-disabled:outline-1 aria-disabled:outline-solid aria-disabled:outline-base-content/25";

const buttonVariants = cva("btn caps-button disabled:pointer-events-none", {
  variants: {
    variant: {
      primary: "btn-primary caps-button-filled",
      secondary: "btn-secondary caps-button-filled",
      accent: "btn-accent caps-button-filled",
      destructive: "btn-error caps-button-filled",
      outline: `btn-outline ${disabledPlate}`,
      // A faceless ghost stays faceless when disabled: Caps dims its ink.
      ghost: "btn-ghost",
      "ghost-destructive": "btn-ghost caps-button-ghost-destructive",
      link: `btn-link ${disabledPlate}`,
    },
    size: {
      xs: "btn-xs",
      sm: "btn-sm",
      default: "btn-md",
      lg: "btn-lg",
      icon: "btn-square btn-md",
      menubar: "caps-button-menubar",
    },
  },
  defaultVariants: { variant: "primary", size: "default" },
});

/** The outcome of a Button's last action. */
export type ButtonResult = "done" | "failed";

/** Props accepted by Button. */
export type ButtonProps = {
  asChild?: boolean;
  loading?: boolean;
  /**
   * The outcome of the last action. Becoming `done` plays a short beat: a
   * check (and `resultLabel`) springs in, holds, then settles back to the
   * label. Becoming `failed` shakes the label by the theme's
   * `--stipe-motion-shake`. Say what failed elsewhere, next to the action.
   */
  result?: ButtonResult | undefined;
  /** What the done beat says, such as "Installed". The button keeps the wider of its two labels, so nothing shifts. */
  resultLabel?: ReactNode;
  /**
   * Called when the done beat has held long enough to read, just before it
   * would settle back to the label. Replace the button here to hand off to
   * what comes next (an "Installed" mark, an "Open" action).
   */
  onResultEnd?: (() => void) | undefined;
  size?: ButtonSize;
  variant?: ButtonVariant;
} & ButtonHTMLAttributes<HTMLButtonElement>;

/** A reusable button with caller-controlled native behavior and intrinsic loading presentation. */
export const Button = forwardRef<HTMLButtonElement, ButtonProps>(
  function Button(
    {
      asChild = false,
      children,
      className,
      disabled,
      loading = false,
      result,
      resultLabel,
      onResultEnd,
      size = "default",
      variant = "primary",
      ...props
    },
    ref,
  ) {
    const classes = cn(buttonVariants({ size, variant }), className);
    // A result present when the button first mounts is history, not news.
    const mountedResult = useRef(result).current;
    const node = useRef<HTMLButtonElement>(null);
    useImperativeHandle<HTMLButtonElement | null, HTMLButtonElement | null>(
      ref,
      () => node.current,
    );
    useWidthTween(node, loading, result);
    if (asChild) {
      return (
        <Slot
          {...props}
          aria-busy={loading ? true : props["aria-busy"]}
          aria-disabled={disabled === true || loading ? true : undefined}
          className={classes}
          ref={node}
        >
          {children}
        </Slot>
      );
    }
    return (
      <button
        {...props}
        aria-busy={loading ? true : props["aria-busy"]}
        className={classes}
        disabled={disabled === true || loading}
        ref={node}
        type={props.type ?? "button"}
      >
        {result === undefined && resultLabel === undefined ? (
          <>
            {loading ? (
              <Loader className="size-3" decorative size="sm" />
            ) : null}
            {children}
          </>
        ) : (
          <ResultFaces
            label={resultLabel}
            loading={loading}
            onResultEnd={onResultEnd}
            result={result}
            settled={mountedResult}
          >
            {children}
          </ResultFaces>
        )}
      </button>
    );
  },
);

/**
 * When a button's label changes (loading, a result, new text) its width eases
 * to the new size instead of jumping, so neighbours never lurch.
 *
 * What counts as "changed" is what the button renders (its text, loading and
 * result), never the identity of its children: a caller that builds a fresh
 * array or element with the same words each render has not changed the label.
 * Widths are layout (CSS) pixels from `offsetWidth`, the unit the animated
 * `width` is in, so a scaled or zoomed ancestor cannot distort the glide. A
 * button that has no box (an ancestor is `display: none`) records no width, so
 * when it is shown it settles at its size instead of growing from nothing.
 */
function useWidthTween(
  node: RefObject<HTMLButtonElement | null>,
  loading: boolean,
  result: ButtonResult | undefined,
) {
  const width = useRef<number | null>(null);
  const look = useRef<string | null>(null);
  const tween = useRef<Animation | null>(null);
  // After every commit: the rendered text is only known once it is in the DOM.
  useLayoutEffect(() => {
    const element = node.current;
    if (!element) return;
    const now = JSON.stringify([loading, result ?? null, element.textContent]);
    const changed = now !== look.current;
    look.current = now;
    const running = tween.current;
    // Nothing new to say: let a glide in progress finish undisturbed.
    if (!changed && running) return;
    const from = running ? element.offsetWidth : width.current;
    if (running) {
      tween.current = null;
      running.cancel();
      element.style.removeProperty("overflow");
      element.style.removeProperty("white-space");
    }
    const to = element.offsetWidth;
    width.current = to > 0 ? to : null;
    if (
      !changed ||
      from === null ||
      to === 0 ||
      Math.abs(from - to) < 1 ||
      !canAnimate(element)
    )
      return;
    const motion = readMotion(element);
    if (motion.reduced) return;
    const animation = element.animate(
      [{ width: `${String(from)}px` }, { width: `${String(to)}px` }],
      { duration: motion.normal, easing: motionEasing(motion, motion.ease) },
    );
    tween.current = animation;
    // Content wider than the moving edge is clipped, never spilled or wrapped.
    element.style.overflow = "clip";
    element.style.whiteSpace = "nowrap";
    const done = () => {
      if (tween.current !== animation) return;
      tween.current = null;
      element.style.removeProperty("overflow");
      element.style.removeProperty("white-space");
    };
    animation.onfinish = done;
    animation.oncancel = done;
  });
}

/** How long the done beat holds before settling: long enough to read. */
const resultHoldMs = 1100;

function pop(faces: HTMLElement, motion: Motion) {
  // One overshoot sized by the theme's bounce; a calm theme just nods.
  const liveliness = motion.bounce / 0.3;
  const lift = 1 + 0.05 * Math.min(1.4, 0.4 + liveliness);
  const dip = 1 - 0.02 * Math.min(1.4, liveliness);
  return faces.animate(
    [
      { transform: "scale(1)" },
      { transform: `scale(${String(lift)})`, offset: 0.35 },
      { transform: `scale(${String(dip)})`, offset: 0.7 },
      { transform: "scale(1)" },
    ],
    {
      duration: motion.springDuration,
      easing: motionEasing(motion, "ease-out"),
    },
  );
}

function shake(faces: HTMLElement, motion: Motion) {
  const x = motion.shake;
  return faces.animate(
    [
      { transform: "none" },
      { transform: `translateX(${String(-x)}px)` },
      { transform: `translateX(${String(x)}px)` },
      { transform: `translateX(${String(-x * 0.6)}px)` },
      { transform: `translateX(${String(x * 0.3)}px)` },
      { transform: "none" },
    ],
    { duration: motion.slow * 1.3, easing: motionEasing(motion, "linear") },
  );
}

function swapFaces(
  leaving: HTMLElement,
  arriving: HTMLElement,
  motion: Motion,
) {
  const travel = motion.distance + 2;
  const blur = `blur(${String(motion.blur)}px)`;
  return [
    leaving.animate(
      [
        { opacity: 1, transform: "none", filter: "blur(0px)" },
        {
          opacity: 0,
          transform: `translateY(${String(-travel)}px)`,
          filter: blur,
        },
      ],
      {
        duration: motion.fast,
        // A label rolls away at once; an ease-in would linger on stale text.
        easing: motionEasing(motion, motion.ease),
      },
    ),
    arriving.animate(
      [
        {
          opacity: 0,
          transform: `translateY(${String(travel)}px)`,
          filter: blur,
        },
        { opacity: 1, transform: "none", filter: "blur(0px)" },
      ],
      {
        duration: motion.normal,
        easing: motionEasing(motion, motion.ease),
        fill: "backwards",
      },
    ),
  ];
}

/** @internal The label and result faces of a Button with a result beat. */
function ResultFaces({
  children,
  label,
  loading,
  onResultEnd,
  result,
  settled,
}: {
  children: ReactNode;
  label: ReactNode;
  loading: boolean;
  onResultEnd: (() => void) | undefined;
  result: ButtonResult | undefined;
  settled: ButtonResult | undefined;
}) {
  const faces = useRef<HTMLSpanElement>(null);
  const reduced = useReducedMotion();
  const [showing, setShowing] = useState(false);
  // The result face exists only for its beat, so it never lingers as hidden
  // text in the button.
  const [resultMounted, setResultMounted] = useState(false);
  if (showing && !resultMounted) setResultMounted(true);
  const previous = useRef(settled);
  const ended = useRef(onResultEnd);
  useEffect(() => {
    ended.current = onResultEnd;
  }, [onResultEnd]);

  // Before paint, so the label never flashes ahead of the beat.
  useLayoutEffect(() => {
    const before = previous.current;
    previous.current = result;
    if (result === before) return;
    if (result === "done") {
      setShowing(true);
      const settle = setTimeout(() => {
        // A caller that hands off keeps the result face until it replaces
        // the button; otherwise the beat settles back to the label.
        if (ended.current) ended.current();
        else setShowing(false);
      }, resultHoldMs);
      return () => {
        clearTimeout(settle);
      };
    }
    setShowing(false);
    const element = faces.current;
    if (result !== "failed" || !element || !canAnimate(element)) return;
    const motion = readMotion(element);
    if (motion.shake <= 0) return;
    const refusal = shake(element, motion);
    return () => {
      refusal.cancel();
    };
  }, [result, reduced]);

  const shown = useRef(showing);
  useLayoutEffect(() => {
    const element = faces.current;
    if (!element || shown.current === showing) return;
    shown.current = showing;
    const labelFace = element.querySelector<HTMLElement>('[data-face="label"]');
    const resultFace = element.querySelector<HTMLElement>(
      '[data-face="result"]',
    );
    if (!labelFace || !resultFace || !canAnimate(element)) {
      if (!showing) setResultMounted(false);
      return;
    }
    const motion = readMotion(element);
    const animations = showing
      ? swapFaces(labelFace, resultFace, motion)
      : swapFaces(resultFace, labelFace, motion);
    if (!showing)
      animations[0]?.addEventListener("finish", () => {
        setResultMounted(false);
      });
    if (showing && !motion.reduced) {
      animations.push(pop(element.closest("button") ?? element, motion));
      const tick = resultFace.querySelector<SVGPathElement>("path");
      if (tick)
        animations.push(
          tick.animate([{ strokeDashoffset: 1 }, { strokeDashoffset: 0 }], {
            duration: motion.normal * 1.4,
            delay: motion.fast / 2,
            easing: motionEasing(motion, motion.ease),
            fill: "backwards",
          }),
        );
    }
    return () => {
      for (const animation of animations) animation.cancel();
    };
  }, [showing, reduced]);

  return (
    <span
      ref={faces}
      className="caps-button-faces"
      data-showing={showing ? "result" : "label"}
    >
      <span
        className="caps-button-face"
        data-face="label"
        aria-hidden={showing ? true : undefined}
      >
        {loading || showing ? (
          <Loader className="size-3" decorative size="sm" />
        ) : null}
        {children}
      </span>
      {resultMounted ? (
        <span
          className="caps-button-face"
          data-face="result"
          aria-hidden={showing ? undefined : true}
        >
          <svg
            className="caps-button-check"
            viewBox="0 0 24 24"
            aria-hidden="true"
            focusable="false"
          >
            <path d="M4.5 12.5 9.5 17.5 19.5 6.5" pathLength={1} />
          </svg>
          {label === undefined ? children : label}
        </span>
      ) : null}
    </span>
  );
}

/** The native element type used by Button. */
export type ButtonElement = ElementRef<"button">;

import { STIPE_SPACING_NAMES } from "@fungi.computer/stipe";
import { cva } from "class-variance-authority";
import { createCn } from "cn/config";

/** A conditional class value accepted by cn. */
export type { ClassValue } from "cn";
export { cva };

/** Merge conditional classes with Tailwind rules and Stipe's named spacing. */
export const cn = createCn({
  extend: { theme: { spacing: [...STIPE_SPACING_NAMES] } },
});

/** Resolve a typed React class-name prop before merging its classes. */
export function resolveClassName<State>(
  className: string | ((state: State) => string | undefined) | undefined,
  state: State,
): string | undefined {
  return typeof className === "function" ? className(state) : className;
}

import {
  useLayoutEffect,
  useState,
  useSyncExternalStore,
  type RefObject,
} from "react";

/** Resolved, element-scoped motion. Times are milliseconds and distances pixels. */
export type Motion = Readonly<{
  reduced: boolean;
  squish: number;
  fast: number;
  normal: number;
  slow: number;
  springDuration: number;
  bounce: number;
  stretch: number;
  distance: number;
  stagger: number;
  blur: number;
  shake: number;
  steps: number;
  fuse: number;
  pressDepth: number;
  pressScale: number;
  ease: string;
  easeExit: string;
}>;

const defaults: Motion = Object.freeze({
  reduced: false,
  squish: 90,
  fast: 120,
  normal: 180,
  slow: 280,
  springDuration: 320,
  bounce: 0.3,
  stretch: 0.28,
  distance: 4,
  stagger: 24,
  blur: 0,
  shake: 3,
  steps: 0,
  fuse: 1,
  pressDepth: 0.5,
  pressScale: 1,
  ease: "cubic-bezier(0.2, 0, 0, 1)",
  easeExit: "cubic-bezier(0.4, 0, 1, 1)",
});

const preference = "(prefers-reduced-motion: reduce)";

/** Read at an event boundary; no root-theme lookup, so nested tokens win. */
export function readMotion(element: Element): Motion {
  const view = element.ownerDocument.defaultView;
  if (!view) return defaults;
  const style = view.getComputedStyle(element);
  const number = (name: string, fallback: number) => {
    const value = style.getPropertyValue(name).trim();
    const parsed = Number.parseFloat(value);
    return Number.isFinite(parsed) ? Math.max(0, parsed) : fallback;
  };
  const time = (name: string, fallback: number) => {
    const value = style.getPropertyValue(name).trim();
    return (
      number(name, fallback) *
      (value.endsWith("s") && !value.endsWith("ms") ? 1000 : 1)
    );
  };
  const browser: Partial<Pick<Window, "matchMedia">> = view;
  const reduced = browser.matchMedia?.(preference).matches ?? false;
  const duration = (name: string, fallback: number) =>
    reduced ? 120 : time(`--stipe-motion-${name}`, fallback);
  const amount = (name: string, fallback: number) =>
    reduced ? 0 : number(`--stipe-motion-${name}`, fallback);
  return {
    reduced,
    squish: duration("squish", defaults.squish),
    fast: duration("fast", defaults.fast),
    normal: duration("normal", defaults.normal),
    slow: duration("slow", defaults.slow),
    springDuration: duration("spring-duration", defaults.springDuration),
    bounce: Math.min(1, amount("bounce", defaults.bounce)),
    stretch: amount("stretch", defaults.stretch),
    distance: amount("distance", defaults.distance),
    stagger: reduced ? 0 : time("--stipe-motion-stagger", defaults.stagger),
    blur: amount("blur", defaults.blur),
    shake: amount("shake", defaults.shake),
    steps: Math.floor(amount("steps", defaults.steps)),
    fuse: number("--stipe-motion-fuse", defaults.fuse),
    pressDepth: reduced
      ? 0
      : number("--stipe-press-depth", defaults.pressDepth),
    pressScale: reduced
      ? 1
      : number("--stipe-press-scale", defaults.pressScale),
    ease: style.getPropertyValue("--stipe-motion-ease").trim() || defaults.ease,
    easeExit:
      style.getPropertyValue("--stipe-motion-ease-exit").trim() ||
      defaults.easeExit,
  };
}

/** Live motion tokens for a mounted ref, including nested theme and OS changes. */
export function useMotion(ref: RefObject<Element | null>): Motion {
  const [motion, setMotion] = useState<Motion>(() => ({
    ...defaults,
    reduced: true,
  }));
  useLayoutEffect(() => {
    const element = ref.current;
    const view = element?.ownerDocument.defaultView;
    if (!element || !view) return;
    const update = () => {
      const next = readMotion(element);
      setMotion((previous) =>
        JSON.stringify(previous) === JSON.stringify(next) ? previous : next,
      );
    };
    update();
    const observer = new view.MutationObserver(update);
    // Observe ancestors only: animation writes to descendants must not trigger reads.
    for (
      let parent: Element | null = element;
      parent;
      parent = parent.parentElement
    ) {
      observer.observe(parent, {
        attributes: true,
        attributeFilter: ["data-theme", "class", "style"],
      });
    }
    const browser: Partial<Pick<Window, "matchMedia">> = view;
    const media = browser.matchMedia?.(preference);
    media?.addEventListener("change", update);
    return () => {
      observer.disconnect();
      media?.removeEventListener("change", update);
    };
  }, [ref]);
  return motion;
}

/** Today's feel: the defaults that components' authored timings are written against. */
export const motionDefaults: Motion = defaults;

/**
 * Scale one of a component's authored durations by the theme's tempo
 * (`--stipe-motion-normal` against its 180ms default). Today's themes return
 * the authored value unchanged; reduced motion returns 0 (nothing travels).
 */
export function motionTime(motion: Motion, authored: number): number {
  if (motion.reduced) return 0;
  return Math.round((authored * motion.normal) / defaults.normal);
}

/**
 * Scale one of a component's authored spring bounces by the theme's bounce
 * (`--stipe-motion-bounce` against its 0.3 default), so a lively control stays
 * livelier than a calm one inside every theme. A 0 theme is critically damped.
 */
export function motionBounce(motion: Motion, authored: number): number {
  if (motion.reduced) return 0;
  const scaled = (authored * motion.bounce) / defaults.bounce;
  return Math.min(0.9, Math.max(0, scaled));
}

/** Scale an authored spring settle time by `--stipe-motion-spring-duration`. */
export function motionSpringTime(motion: Motion, authored: number): number {
  if (motion.reduced) return 0;
  return Math.round(
    (authored * motion.springDuration) / defaults.springDuration,
  );
}

/** A CSS easing for a Web Animation, stepped when the theme asks for it. */
export function motionEasing(motion: Motion, ease: string): string {
  return motion.steps > 0 ? `steps(${String(motion.steps)}, end)` : ease;
}

/** Whether the element can run Web Animations (not in jsdom or old engines). */
export function canAnimate(element: Element): boolean {
  return "animate" in element;
}

const globalWindow: Partial<Pick<Window, "matchMedia">> = globalThis;

function prefersReducedMotion(): boolean {
  return globalWindow.matchMedia?.(preference).matches ?? false;
}

function subscribeReducedMotion(update: () => void) {
  const media = globalWindow.matchMedia?.(preference);
  media?.addEventListener("change", update);
  return () => {
    media?.removeEventListener("change", update);
  };
}

/** Server renders assume reduced motion, so hydration never starts mid-move. */
function serverReducedMotion() {
  return true;
}

/**
 * The live reduced-motion preference alone, for controls that only need to
 * know whether to move (their timing comes from `readMotion` when they do).
 */
export function useReducedMotion(): boolean {
  return useSyncExternalStore(
    subscribeReducedMotion,
    prefersReducedMotion,
    serverReducedMotion,
  );
}
